S=/private/tmp/claude-501/-Users-akima-workspace-claude-plugins/9d339953-5402-4d6b-b2d3-d3e14ba4f15a/scratchpad; cd /Users/akima/workspace/claude-plugins && cat > $S/chains.py <<'EOF'
import json, re, sys, random
from collections import Counter, defaultdict
S = sys.argv[1]
fs = json.load(open(S + '/findings.json'))
ad = [f for f in fs if f['verdict'] == 'adopted']
hit = json.load(open(S + '/hit.json'))
bysha = defaultdict(list)
for f in ad:
    if f['sha']: bysha[(f['rec'], str(f['sha'])[:7])].append(f)
rev = re.compile(r'取り消|revert|に戻す|を戻す|外す|外し、|消す|削る|やめ|持たない|参照に|リンクに|1 か所に|書かない')
pairs = []
for f in hit:
    shas = set(re.findall(r'\b[0-9a-f]{7,8}\b', f['cause'] + ' ' + f['reason']))
    src = []
    for s in shas:
        for e in bysha.get((f['rec'], s[:7]), []):
            if e['run'] < f['run']: src.append(e)
    if src: pairs.append((f, src))
print('fix-cited findings with a resolvable earlier plan:', len(pairs), '/', len(hit))
revp = [(f, src) for f, src in pairs if rev.search(f['approach'])]
print('of which the later approach removes/reverts/replaces-by-reference:', len(revp))
# 連鎖の長さ: 修正が引かれ、その修正を生んだ指摘もまた別の修正を引いている
hk = {(f['rec'], f['run'], f['id']): f for f in hit}
depth = Counter()
def d(f, seen=()):
    best = 1
    for g, src in pairs:
        if g is f:
            for e in src:
                k = (e['rec'], e['run'], e['id'])
                if k in hk and k not in seen:
                    best = max(best, 1 + d(hk[k], seen + (k,)))
    return best
pm = {id(f): src for f, src in pairs}
for f, src in pairs: depth[d(f)] += 1
print('chain depth (1 = caused by a fix of an original finding):', sorted(depth.items()))
# 元の指摘の severity
print('severity of the earlier findings whose fix was later cited:', Counter(e['sev'] for f, src in pairs for e in src[:1]).most_common(5))
random.seed(3)
for f, src in random.sample(revp, 9):
    e = src[0]
    print(f"\n## {f['rec']}")
    print(f" EARLIER r{e['run']} #{e['id']} sev={e['sev']} [{(e['file'] or '')[-50:]}]")
    print('  S:', e['summary'][:230]); print('  A:', e['approach'][:230])
    print(f" LATER r{f['run']} #{f['id']} sev={f['sev']}")
    print('  S:', f['summary'][:200]); print('  C:', f['cause'][:230]); print('  A:', f['approach'][:230])
EOF
python3 $S/chains.py $S

