python3 - <<'EOF'
import glob, yaml, random, os
from collections import Counter
cat = Counter(); rows = []
for p in sorted(glob.glob('tmp/review-triages/*.yaml') + glob.glob('docs/review-triage/*.yaml')):
    name = os.path.basename(p)[:-5]
    for ri, run in enumerate((yaml.safe_load(open(p)) or {}).get('runs') or [], 1):
        f2p = {}
        for pl in run.get('plans') or []:
            for i in pl.get('finding_ids') or []: f2p[i] = pl
        for f in run.get('findings') or []:
            if f.get('verdict') != 'adopted': continue
            k = 'doc' if (f.get('file') or '').endswith('.md') else 'code'
            cat[(k, (f.get('attrs') or {}).get('category'))] += 1
            pl = f2p.get(f.get('id'))
            if pl and pl.get('approach'): rows.append((k, name, ri, f.get('id'), f.get('summary') or '', pl.get('approach')))
for k in ('doc', 'code'):
    print(k, [(c, n) for (kk, c), n in cat.most_common() if kk == k][:12])
random.seed(11)
for k in ('code', 'doc'):
    sub = [r for r in rows if r[0] == k and r[1] != 'feat-issue-dispatch-plan-114']
    for r in random.sample(sub, 22):
        print(f"\n[{k}] {r[1]} r{r[2]}#{r[3]}\n S: {r[4][:170]}\n A: {r[5][:190]}")
EOF

